-- Generated by tools/cards.py. Upserts all cards, deactivates side quests no longer listed.
-- Re-running overwrites admin edits made on the same ids.
on conflict (id) do update set
  mode = excluded.mode, title = excluded.title, body = excluded.body, tip = excluded.tip,
  difficulty = excluded.difficulty, place = excluded.place, duo = excluded.duo, tone = excluded.tone,
  crush = excluded.crush, day = excluded.day, week = excluded.week, checkpoint = excluded.checkpoint,
  active = true, updated_at = now();

update public.cards set active = false, updated_at = now()
where mode = 'situation' and id not in ('s-class-notes', 's-class-pen', 's-class-out-loud', 's-class-after-class', 's-class-new-seat', 's-class-verdict', 's-class-study-group', 's-class-i-disagree', 's-class-lunch', 's-class-to-the-board', 's-class-announcement', 's-class-join-the-project', 's-class-second-look', 's-class-five-minutes', 's-class-trivia', 's-class-snack-round', 's-class-autograph', 's-class-standing-ovation', 's-class-theme-day', 's-class-new-faces', 's-class-question-relay', 's-class-settle-it', 's-class-pen-please', 's-class-compare-notes', 's-class-walk-out-together', 's-class-coffee-after-class', 's-class-rate-my-doodle', 's-library-charger', 's-library-free-seat', 's-library-guard-my-stuff', 's-library-librarian-s-pick', 's-library-what-s-that', 's-library-explain-it', 's-library-window-seat', 's-library-lower-it', 's-library-coffee-break', 's-library-study-partner', 's-library-book-oracle', 's-library-dragon-cookbook', 's-library-whisper-review', 's-library-two-whispers', 's-library-highlighter', 's-library-study-break', 's-cafe-barista-s-choice', 's-cafe-wifi', 's-cafe-shared-table', 's-cafe-worth-it', 's-cafe-taste-first', 's-cafe-free-refill', 's-cafe-ten-minutes', 's-cafe-their-story', 's-cafe-on-the-house', 's-cafe-behind-the-counter', 's-cafe-table-talk', 's-cafe-bad-joke', 's-cafe-dj-request', 's-cafe-foam-art', 's-cafe-name-a-drink', 's-cafe-pastry-judge', 's-cafe-sung-order', 's-cafe-round-of-applause', 's-cafe-two-tables', 's-cafe-join-in', 's-cafe-surprise-me', 's-cafe-the-smile', 's-cafe-your-order', 's-cafe-mind-if-i-sit', 's-cafe-second-coffee', 's-cafe-rate-the-art', 's-street-the-dog', 's-street-local-tip', 's-street-photo-swap', 's-street-five-hellos', 's-street-what-do-you-think', 's-street-best-advice', 's-street-five-compliments', 's-street-walk-with-me', 's-street-bench-talk', 's-street-one-euro', 's-street-sell-it', 's-street-busker', 's-street-count-to-ten', 's-street-rock-paper-scissors', 's-street-superhero-name', 's-st